import { useEffect, useReducer } from 'react';

import { seedThreads } from '../data/seedMailbox';
import { SYSTEM_LABELS } from '../domain/mail';
import type {
  ComposeDraft,
  Contact,
  MailCategory,
  MailMessage,
  MailboxId,
  MailThread,
  StoredFolder,
  ToastState,
} from '../domain/mail';

const STORAGE_KEY = 'gpt-5-6-sol-mailbox-v1';
const PERSISTENCE_VERSION = 1;
const TOAST_DURATION_MS = 4_500;
const UNDO_TOAST_DURATION_MS = 7_000;
const MAX_TIMEOUT_MS = 2_147_483_647;
const DEFAULT_CATEGORY: MailCategory = 'primary';

const MAILBOX_IDS = [
  'inbox',
  'starred',
  'snoozed',
  'sent',
  'drafts',
  'archive',
  'trash',
] as const satisfies readonly MailboxId[];

const STORED_FOLDERS = [
  'inbox',
  'sent',
  'drafts',
  'archive',
  'trash',
] as const satisfies readonly StoredFolder[];

const MAIL_CATEGORIES = [
  'primary',
  'promotions',
  'social',
  'updates',
] as const satisfies readonly MailCategory[];

const ACCOUNT: Contact = {
  name: 'Alex Morgan',
  email: 'alex.morgan@gmail.com',
  avatar: 'AM',
  color: '#0b57d0',
};

const CONTACT_COLORS = [
  '#1a73e8',
