}

type MailboxAction =
  | { type: 'set-mailbox'; mailbox: MailboxId }
  | { type: 'set-category'; category: MailCategoryFilter }
  | { type: 'set-search'; query: string }
  | { type: 'set-selection'; ids: string[] }
