          ],
          composeDraft: null,
          selectedThreadIds: [],
          activeThreadId: null,
        },
        'Message sent',
      );

    case 'show-toast':
      return { ...state, ...createToast(state, action.message) };

    case 'dismiss-toast':
      return state.toast?.id === action.id ? { ...state, toast: null } : state;

    case 'undo':
      if (!state.undo) return state;
      return {
        ...state,
        ...state.undo,
        ...createToast(state, 'Action undone'),
        undo: null,
