function threadSearchText(thread: MailThread): string {
  const messageText = thread.messages
    .map((message) =>
      [
        message.sender.name,
        message.sender.email,
        searchableContacts(message.recipients),
        message.body.join(' '),
        message.attachments.map((attachment) => attachment.name).join(' '),
      ].join(' '),
