    .join(' ');

  return normalize(
    [
      thread.subject,
      thread.snippet,
      thread.labels.join(' '),
      searchableContacts(thread.participants),
      messageText,
    ].join(' '),
  );
}

function tokenizeSearch(query: string): string[] {
  return query.match(/(?:[^\s"]+:"[^"]*"|"[^"]*"|\S+)/g) ?? [];
